sys_script.script:
(function executeRule(current, previous) {

    if (current.getValue('queue') != 'input') return;

    var topic = current.getValue('topic') || '';
    var sendOne = topic.indexOf('ONPAGE_SEND_MESSAGE_') === 0;
    var sendMany = topic.indexOf('ONPAGE_SEND_MESSAGES_') === 0;

    if (!sendOne && !sendMany) return;

    try {
        var payload = current.getValue('payload');
        if (!payload) throw new Error('ECC response payload is empty.');

        var xml = new XMLDocument2();
        xml.parseXML(payload);

        var statusNode = xml.getNode('//parameters/parameter[@name="http_status_code"]');
        var status = statusNode ? statusNode.getAttribute('value') : '';

        var outputNode = xml.getNode('//result/output');
        var body = outputNode ? outputNode.getTextContent() : '';

        var rootNode = xml.getDocumentElement();
        var errorMessage = rootNode ? rootNode.getAttribute('error') : '';

        if (!status) throw new Error('HTTP status code not found in ECC response.');

        if (sendOne) {
            var remaining = topic.substring('ONPAGE_SEND_MESSAGE_'.length);
            var separator = remaining.lastIndexOf('_');
            if (separator < 1) throw new Error('Invalid topic: ' + topic);
            var notifId = remaining.substring(0, separator);

            var gr = new GlideRecord('x_onpr_onpage_notification');
            if (!gr.get(notifId)) throw new Error('Notification not found: ' + notifId);

            if (String(status) != '200') {
                gr.setValue('status', 'error');
                gr.setValue('error', body || errorMessage || status);
                gr.update();
                return;
            }

            var json = JSON.parse(body);
            if (json[0].accepted == true) {
                gr.setValue('status', 'sent');
                gr.setValue('onpage_id', json[0].id);
                gr.setValue('error', '');
            } else {
                gr.setValue('status', 'error');
                gr.setValue('error', json[0].errorDescription);
            }
            gr.update();
            return;
        }

        if (sendMany) {
            var bulkJson = null;
            if (String(status) == '200') {
                try {
                    bulkJson = JSON.parse(body);
                } catch(e) {
                    gs.error('OnPage bulk response parse failed. Topic: ' + topic + ' | Error: ' + e.message);
                    return;
                }
            }

            var gr3 = new GlideRecord('x_onpr_onpage_notification');
            gr3.addQuery('status', 'sending');
            gr3.orderBy('sys_id');
            gr3.query();
            var k = 0;
            while (gr3.next()) {
                if (String(status) != '200') {
                    gr3.setValue('status', 'error');
                    gr3.setValue('error', body || errorMessage || status);
                } else {
                    var obj = bulkJson ? bulkJson[k] : null;
                    if (!obj) {
                        gr3.setValue('status', 'error');
                        gr3.setValue('error', 'No result returned for this message');
                    } else if (obj.accepted) {
                        gr3.setValue('status', 'sent');
                        gr3.setValue('error', '');
                    } else {
                        gr3.setValue('status', 'error');
                        gr3.setValue('error', obj.errorDescription);
                    }
                }
                gr3.update();
                k++;
            }
            return;
        }

    } catch (ex) {
        gs.error('OnPage ECC sendMessage response failed. Topic: ' + topic + ' | Error: ' + ex.message);
    }

})(current, previous);
